ValidationRule.errorConditionFormula:
AND (
  ISCHANGED(SBQQ__Status__c),
  OR (
    AND (
      ISPICKVAL(PRIORVALUE(SBQQ__Status__c), "Expired"),
      NOT(ISPICKVAL(SBQQ__Status__c, "Rejected"))
    ),
    AND (
      ISPICKVAL(PRIORVALUE(SBQQ__Status__c), "Rejected"),
      NOT(ISPICKVAL(SBQQ__Status__c, "Expired"))
    )
  )
)
